mapper.select:
SELECT s.id AS studentId, s.student_no AS studentNo, s.name AS studentName, s.class_name AS className, sc.id AS scoreId, sc.score AS score FROM student s LEFT JOIN score sc ON sc.student_id = s.id AND sc.exam_id = #{examId}
AND s.class_name = #{className}
ORDER BY s.student_no

SELECT c.id AS courseId, c.name AS courseName, ROUND(AVG(sc.score * 100.0 / e.full_score), 1) AS avgScore, ROUND(SUM(CASE WHEN sc.score * 100.0 / e.full_score >= 60 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 1) AS passRate FROM course c JOIN exam e ON e.course_id = c.id JOIN score sc ON sc.exam_id = e.id
AND c.teacher_id = #{teacherId}
GROUP BY c.id, c.name ORDER BY c.id
